import {requireRuntime} from './runtime.mjs';
import {AsyncLocalStorage} from 'node:async_hooks';
import {randomUUID} from 'node:crypto';
import {spawn} from 'node:child_process';
import {connect} from 'node:net';
import {createInterface} from 'node:readline';
import {mkdtemp,readFile,rm} from 'node:fs/promises';
import {join} from 'node:path';
import {tmpdir} from 'node:os';
import {PublishingStore} from '../../routes/project-store.mjs';
const {Pool}=requireRuntime('pg'),express=requireRuntime('express'),root=new URL('../../',import.meta.url);
export function exchange(port,request){return new Promise((done,reject)=>{const socket=connect(port,'127.0.0.1');let raw='',hello,ended=false;const timer=setTimeout(()=>finish(new Error('Publishing fixture engine deadline')),20000);function finish(error,value){if(ended)return;ended=true;clearTimeout(timer);socket.destroy();error?reject(error):done(value);}socket.on('error',finish);socket.on('close',()=>{if(!ended)finish(new Error('Publishing fixture incomplete engine frame'));});socket.on('data',bytes=>{raw+=bytes;if(raw.length>1024*1024)return finish(new Error('Publishing fixture oversized frame'));for(;;){const n=raw.indexOf('\n');if(n<0)break;let value;try{value=JSON.parse(raw.slice(0,n));}catch{return finish(new Error('Publishing fixture invalid frame'));}raw=raw.slice(n+1);if(!hello){hello=value;socket.write(JSON.stringify({id:1,...request})+'\n');}else return finish(null,{hello,reply:value});}});});}
export async function fixture({http=false}={}){
 const raw=process.env.OSHAL_TEST_POSTGRES;if(!raw)throw new Error('OSHAL_TEST_POSTGRES must select shared disposable127.0.0.1:35689');const selected=new URL(raw);if(!['postgres:','postgresql:'].includes(selected.protocol)||selected.hostname!=='127.0.0.1'||selected.port!=='35689')throw new Error('Only disposable PG127.0.0.1:35689');
 const python=process.env.OSHAL_PUBLISHING_PYTHON,typst=process.env.OSHAL_PUBLISHING_TYPST;if(!python||!typst)throw new Error('Genuine prepared OSHAL_PUBLISHING_PYTHON and OSHAL_PUBLISHING_TYPST required; no skip/fallback');
 const suffix=randomUUID().replaceAll('-',''),database='publishing_source_'+suffix,role='publishing_role_'+suffix,password=randomUUID(),admin=new Pool({connectionString:selected.href}),directory=await mkdtemp(join(tmpdir(),'publishing-source-')),als=new AsyncLocalStorage();
 let db,pool,child,server,closed=false;const poolErrors=[],states=new Map(['alice','bob'].map(owner=>[owner,{identity:{issuer:'publishing-source',sub:owner,principalId:'principal-'+owner,tenantIds:['tenant-source']},active:true,denied:new Set(),hook:null,sqlHook:null,sqlAfter:null}]));
 async function close(){if(closed)return;closed=true;const failures=[];if(server)await new Promise(resolve=>server.close(resolve));if(child){child.kill('SIGTERM');await new Promise(resolve=>{if(child.exitCode!==null)return resolve();const timer=setTimeout(()=>child.kill('SIGKILL'),5000);child.once('exit',()=>{clearTimeout(timer);resolve();});});}await pool?.end();await db?.end();try{const deadline=Date.now()+5000;while((await admin.query('SELECT count(*)::int AS n FROM pg_stat_activity WHERE datname=$1',[database])).rows[0].n){if(Date.now()>=deadline)throw new Error('Publishing own SQL connections did not close');await new Promise(resolve=>setTimeout(resolve,20));}await admin.query('DROP DATABASE IF EXISTS '+database);}catch(error){failures.push(error);}try{await admin.query('DROP ROLE IF EXISTS '+role);}catch(error){failures.push(error);}await admin.end();await rm(directory,{recursive:true,force:true});if(poolErrors.length||failures.length)throw new AggregateError([...poolErrors,...failures],'Publishing fixture cleanup failed');}
 try{
  await admin.query('CREATE DATABASE '+database);await admin.query(`CREATE ROLE ${role} LOGIN PASSWORD '${password}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS`);const dbUrl=new URL(selected);dbUrl.pathname='/'+database;db=new Pool({connectionString:dbUrl.href});await db.query(await readFile(new URL('../../migrations/001-publishing-studio.sql',import.meta.url),'utf8'));await db.query(`GRANT USAGE ON SCHEMA public TO ${role};GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO ${role}`);dbUrl.username=role;dbUrl.password=password;pool=new Pool({connectionString:dbUrl.href,max:12});pool.on('error',error=>poolErrors.push(error));db.on('error',error=>poolErrors.push(error));
  child=spawn(python,[new URL('../../engine/server.py',import.meta.url).pathname],{env:{PATH:'/usr/bin:/bin',LANG:'C.UTF-8',PYTHONDONTWRITEBYTECODE:'1',TMPDIR:directory,OSHAL_PUBLISHING_TYPST:typst,PUBLISHING_ENGINE_HOST:'127.0.0.1',PUBLISHING_ENGINE_PORT:'0'},stdio:['ignore','pipe','pipe']});let stderr='';child.stderr.on('data',data=>{stderr=(stderr+data.toString()).slice(-4096);});const lines=createInterface({input:child.stdout});const ready=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Publishing genuine engine startup deadline')),15000);lines.once('line',line=>{clearTimeout(timer);try{resolve(JSON.parse(line));}catch(error){reject(error);}});child.once('error',reject);child.once('exit',()=>{clearTimeout(timer);reject(new Error('Publishing genuine engine exited '+stderr));});});lines.close();
  function context(owner){const state=states.get(owner);if(!state)throw new Error('Unknown fixture owner');const ctx={appPackageDir:root.pathname,pool:{connect:async()=>{const client=await pool.connect();return{query:async(sql,params)=>{if(state.sqlHook)await state.sqlHook(sql,params);const result=await client.query(sql,params);if(state.sqlAfter)await state.sqlAfter(sql,params,result);return result;},release:()=>client.release()};}},authorization:{registerResource:()=>{},currentActor:()=>({...state.identity,isActive:state.active}),authorize:async({permission})=>({allowed:state.active&&!state.denied.has(permission)})},intent:async(name,input)=>{if(name!=='engine.exchange')throw new Error('Source fixture does not fake native artifact/import ports');const result=await exchange(ready.port,input.request);if(state.hook)await state.hook(input.request.args,result);return result;}};return{state,ctx,store:new PublishingStore(ctx)};}
  const ctx={appPackageDir:root.pathname,pool:{connect:()=>context(als.getStore()??'alice').ctx.pool.connect()},authorization:{registerResource:()=>{},currentActor:()=>context(als.getStore()??'alice').ctx.authorization.currentActor(),authorize:input=>context(als.getStore()??'alice').ctx.authorization.authorize(input)},intent:(name,input)=>context(als.getStore()??'alice').ctx.intent(name,input)};
  const kept=new Map(),runs={keepRunAlive:async id=>kept.set(id,als.getStore()??'alice'),run:async(id,work)=>{if(!kept.has(id))throw new Error('Source fixture continuation was not captured');return als.run(kept.get(id),work);},runFinished:async id=>kept.delete(id)};
  if(http){const {createPublishingRoutes}=await import('../../routes/application.mjs');const app=express();app.use((req,_res,next)=>als.run(req.headers['x-test-owner']??'alice',next));app.use('/api/publishing-studio',createPublishingRoutes(ctx,runs));server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));}
  return{ctx,context,states,db,pool,directory,as:(owner,work)=>als.run(owner,work),url:server?'http://127.0.0.1:'+server.address().port:null,close,kept,enginePort:ready.port,identity:ready.identity};
 }catch(error){try{await close();}catch(cleanup){throw new AggregateError([error,cleanup],'Publishing setup/cleanup failed');}throw error;}
}
